import openpyxl

wb = openpyxl.load_workbook('gdp.xlsx')
ws = wb['Data']

# Check Data sheet row 4 (header) and the data range rows 21-40
print("=== Data sheet Row 4 (headers) ===")
for c in range(1, 20):
    cell = ws.cell(row=4, column=c)
    if cell.value:
        print(f"  {cell.coordinate}: {cell.value}")

print("\n=== Data rows 5-10 ===")
for r in range(5, 11):
    vals = []
    for c in range(1, 14):
        cell = ws.cell(row=r, column=c)
        if cell.value is not None:
            vals.append(f"{cell.coordinate}={cell.value}")
    if vals:
        print(f"  Row {r}: {'; '.join(vals)}")

# Check if there are rows between the datasets (row 20, 27, 34)
for r in [20, 27, 34]:
    vals = []
    for c in range(1, 14):
        cell = ws.cell(row=r, column=c)
        if cell.value is not None:
            vals.append(f"{cell.coordinate}={cell.value}")
    print(f"\n  Row {r}: {vals if vals else 'EMPTY'}")

# Check Task sheet rows 42-50 for H-L columns
ws2 = wb['Task']
print("\n=== Task rows 42-50 cols H-L ===")
for r in range(42, 51):
    for c in range(8, 13):
        cell = ws2.cell(row=r, column=c)
        print(f"  {cell.coordinate}: value={cell.value}, fill patternType={cell.fill.patternType}")
